published_replay.py.source:
"""Replay bounded dogfood cases against an explicitly identified installed artifact.

Run outside every checkout, without PYTHONPATH. All writable fixtures are temporary.
Installer and GPU producer controls are deliberately injected; the optional native
probe is a separate real-process observation and never claims hardware availability.
"""
from __future__ import annotations

import argparse
import asyncio
import base64
from contextlib import ExitStack
import hashlib
import importlib.metadata
import json
import os
from pathlib import Path
import subprocess
import sys
import tempfile
from unittest.mock import patch

from typer.testing import CliRunner

import tensor_grep
from tensor_grep import rust_core
from tensor_grep.cli import main, repair_env


def checkpoint_list_matches(payload, checkpoint_id, label):
    return isinstance(payload, dict) and any(
        isinstance(item, dict)
        and item.get('checkpoint_id') == checkpoint_id
        and item.get('label') == label
        for item in payload.get('checkpoints', [])
    )


def snapshot_tree(root):
    snapshot = {}
    for path in sorted(root.rglob('*')):
        assert not path.is_symlink(), path
        snapshot[path.relative_to(root).as_posix()] = (
            {'kind': 'directory'} if path.is_dir()
            else {'kind': 'file', 'bytes_hex': path.read_bytes().hex()}
        )
    return snapshot


def refusal_unchanged(payload, before, after):
    return payload.get('error', {}).get('code') == 'invalid_input' and before == after


def main_replay() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument('--cases', default='diagnostics,decoding,ranking,labels')
    parser.add_argument('--version')
    parser.add_argument('--require-wheel', action='store_true')
    parser.add_argument('--native')
    args = parser.parse_args()
    selected = set(args.cases.split(','))
    assert selected and selected <= {'diagnostics', 'decoding', 'ranking', 'labels', 'native'}, selected
    assert 'native' not in selected or args.native, '--cases native requires --native'
    version = importlib.metadata.version('tensor-grep')
    origin = Path(tensor_grep.__file__).resolve()
    report = {'version': version, 'python': sys.executable, 'package': str(origin), 'rows': []}
    extension = Path(rust_core.__file__).resolve()
    report['compiled_extension'] = {'path': str(extension), 'sha256': hashlib.sha256(extension.read_bytes()).hexdigest()}
    if args.version:
        assert version == args.version, (version, args.version)
    if args.require_wheel:
        assert 'site-packages' in origin.parts, origin
        assert 'site-packages' in extension.parts, extension
        distribution = importlib.metadata.distribution('tensor-grep')
        direct = json.loads(distribution.read_text('direct_url.json') or '{}')
        assert not direct.get('dir_info', {}).get('editable'), direct
    runner = CliRunner()
    real_run = subprocess.run

    def row(name, raw, passed):
        report['rows'].append({'issue': name, 'raw': raw, 'verdict': 'PASS' if passed else 'FAIL'})

    with tempfile.TemporaryDirectory(prefix='tg-published-dogfood-') as temp:
        fixture = Path(temp)
        if 'diagnostics' in args.cases.split(','):
            editable = fixture / 'editable'
            editable.mkdir()
            (editable / 'pyproject.toml').write_text('[project]\nname="tensor-grep"\nversion="0.0.0"\n', encoding='utf-8')
            for case in ('utf8_malformed', 'absent_output', 'timeout'):
                observed = {}

                def installer(command, **kwargs):
                    observed.update(kwargs)
                    if case == 'absent_output':
                        return subprocess.CompletedProcess(command, 17, None, None)
                    if case == 'timeout':
                        raise subprocess.TimeoutExpired(command, kwargs['timeout'])
                    return real_run([sys.executable, '-c', "import sys; sys.stderr.buffer.write(b'installer: \\xe2\\x98\\x83 bad=\\xff'); sys.exit(7)"], **kwargs)

                with ExitStack() as stack:
                    stack.enter_context(patch.object(repair_env.runtime_paths, '_repo_root', return_value=editable))
                    stack.enter_context(patch.object(repair_env, 'editable_install_points_at', return_value=(True, version)))
                    stack.enter_context(patch.object(repair_env.shutil, 'which', return_value=None))
                    stack.enter_context(patch.object(repair_env.subprocess, 'run', side_effect=installer))
                    result = runner.invoke(main.app, ['repair-env', '--json'])
                try:
                    payload = json.loads(result.stdout)
                except json.JSONDecodeError:
                    payload = {}
                expected = {'utf8_malformed': 'installer: \u2603 bad=\ufffd', 'absent_output': 'Process exited with 17', 'timeout': 'timed out'}[case]
                row('repair_env_' + case, {'exit': result.exit_code, 'payload': payload, 'stdout': result.stdout, 'exception': None if result.exception is None else {'type': type(result.exception).__name__, 'message': str(result.exception)}, 'producer_kwargs': observed}, result.exit_code == 1 and expected in payload.get('error', '') and observed.get('encoding') == 'utf-8' and observed.get('errors') == 'replace')

            fake_binary = fixture / 'producer-control.exe'
            fake_binary.write_bytes(b'not executed')
            for backend, sidecar in [('NativeGpuBackend', False), ('GpuSidecar', True), ('NativeGpuBackend', None)]:
                payload = {'routing_backend': backend, 'sidecar_used': sidecar}
                observed = {}

                def gpu_producer(command, **kwargs):
                    observed['argv'] = command
                    observed['timeout'] = kwargs.get('timeout')
                    return subprocess.CompletedProcess(command, 0, json.dumps(payload), '')

                with patch.object(main, 'is_cross_domain_native_binary', return_value=False), patch.object(main.subprocess, 'run', side_effect=gpu_producer):
                    output = main._doctor_gpu_search_runtime_probe(fake_binary)
                expected = 'supported' if backend == 'NativeGpuBackend' and sidecar is False else 'unsupported'
                row('gpu_proof_' + backend + '_' + str(sidecar), {'injected_producer': payload, 'consumer': output, **observed}, output['status'] == expected and '-F' not in observed['argv'] and '--' in observed['argv'])

            with patch.object(main, 'is_cross_domain_native_binary', return_value=False), patch.object(main.subprocess, 'run', return_value=subprocess.CompletedProcess(['control'], 0, '[]', '')):
                try:
                    output = main._doctor_gpu_search_runtime_probe(fake_binary)
                except Exception as error:
                    output = {'exception': type(error).__name__, 'message': str(error)}
            row('gpu_non_object_json', output, output.get('status') == 'failed' and output.get('error') == 'GPU runtime probe returned invalid JSON object: expected a JSON object')

        if 'decoding' in args.cases.split(','):
            from tensor_grep.backends.ast_wrapper_backend import AstGrepWrapperBackend
            from tensor_grep.backends.base import BackendExecutionError
            from tensor_grep.backends import ripgrep_backend
            from tensor_grep.cli import agent_capsule, audit_manifest
            from tensor_grep.core.config import SearchConfig

            ast = AstGrepWrapperBackend()
            for name, stdout, stderr, expected_error in (
                ('positive', b'[]', b'warning', False),
                ('malformed_stderr', b'[]', b'warning\xff', False),
                ('malformed_stdout', b'[\xff]', b'warning', True),
            ):
                code = f'import sys; sys.stdout.buffer.write({stdout!r}); sys.stderr.buffer.write({stderr!r})'
                command = [sys.executable, '-B', '-c', code]
                try:
                    completed = ast._run_ast_grep_command(command)
                    raw = {'argv': command, 'returncode': completed.returncode, 'stdout': completed.stdout, 'stderr': completed.stderr}
                    passed = not expected_error and completed.returncode == 0 and completed.stdout == '[]' and completed.stderr == stderr.decode('utf-8', errors='replace')
                except BackendExecutionError as error:
                    raw = {'argv': command, 'exception': type(error).__name__, 'message': str(error)}
                    passed = expected_error and str(error) == 'ast-grep command returned invalid UTF-8 protocol output.'
                row('decoding_ast_' + name, raw, passed)

            echo = [sys.executable, '-B', '-c', 'import sys; sys.stdout.buffer.write(sys.stdin.buffer.read())']
            completed = ast._run_ast_grep_command(echo, input_text='snowman \u2603')
            row('decoding_ast_utf8_input', {'stdout': completed.stdout, 'stderr': completed.stderr, 'returncode': completed.returncode}, completed.stdout == 'snowman \u2603' and completed.returncode == 0)

            def git_failure(command, **kwargs):
                timeout = kwargs.pop('timeout_seconds')
                return real_run([sys.executable, '-B', '-c', "import sys; sys.stderr.buffer.write(b'fatal unresolved\\xff'); sys.exit(128)"], timeout=timeout, **kwargs)

            try:
                with patch.object(audit_manifest, 'run_subprocess', side_effect=git_failure):
                    resolved, error = audit_manifest._resolve_git_ref_commit_sha('missing', root=fixture)
                raw = {'resolved': resolved, 'error': error}
                passed = resolved is None and error == "Could not resolve --against ref 'missing': fatal unresolved\ufffd"
            except Exception as error:
                raw = {'exception': type(error).__name__, 'message': str(error)}
                passed = False
            row('decoding_git_error', raw, passed)

            fake_native = fixture / 'decoding-producer.exe'
            fake_native.write_bytes(b'producer is replaced by a bounded Python child')
            for exit_code in (0, 17):
                child = [sys.executable, '-B', '-c', f"import sys; sys.stdout.buffer.write(b'{{\\xff}}'); sys.stderr.buffer.write(b'GPU unavailable\\xff'); sys.exit({exit_code})"]
                output = agent_capsule._run_agent_gpu_json_command(child, timeout_s=5)
                expected = 'malformed' if exit_code == 0 else 'failed'
                row('decoding_agent_exit_' + str(exit_code), output, output.get('status') == expected and output.get('exit_code') == exit_code and output.get('stderr') == 'GPU unavailable\ufffd')

                def gpu_failure(command, **kwargs):
                    return real_run(child, **kwargs)

                with patch.object(main, 'is_cross_domain_native_binary', return_value=False), patch.object(main.subprocess, 'run', side_effect=gpu_failure):
                    output = main._doctor_gpu_search_runtime_probe(fake_native)
                diagnostic_ok = 'invalid UTF-8' in str(output.get('error')) if exit_code == 0 else output.get('error') == 'GPU unavailable\ufffd'
                row('decoding_doctor_exit_' + str(exit_code), output, output.get('status') == 'failed' and output.get('exit_code') == exit_code and diagnostic_ok)

            from tensor_grep.cli import native_frontdoor
            for stream in ('stdout', 'stderr'):
                for malformed in (False, True):
                    wire = b'Available versions: 1.2\xff.3\n' if malformed else b'Available versions: 1.2.3\n'
                    child = [sys.executable, '-B', '-c', f'import sys; sys.{stream}.buffer.write({wire!r})']

                    def pip_output(command, **kwargs):
                        return real_run(child, **kwargs)

                    with patch.object(main.subprocess, 'run', side_effect=pip_output):
                        output = native_frontdoor._candidate_versions_from_pip_index(5)
                    row('decoding_pip_' + stream + ('_malformed' if malformed else '_valid'), {'wire_hex': wire.hex(), 'versions': output}, output == ([] if malformed else ['1.2.3']))

            from tensor_grep.cli import mcp_server  # Register the facade before its late-bound helpers.
            from tensor_grep.cli import mcp_rewrite_tools, subprocess_policy
            partial = {'matches': [{'file': 'partial.py', 'line_number': 1, 'text': 'x'}], 'total_matches': 1, 'result_incomplete': True, 'incomplete_reason_class': 'scan_limit'}
            for case, wire, error_wire, code in (
                ('index_partial', json.dumps(partial).encode('utf-8'), b'', 2),
                ('diff_content', b'--- a\n+++ b\n-\xff\n', b'', 0),
                ('index_invalid_protocol', b'{\xff}', b'', 0),
                ('index_failed_protocol', b'{\xff}', b'invalid pattern\xff', 17),
            ):
                child = [sys.executable, '-B', '-c', f'import sys; sys.stdout.buffer.write({wire!r}); sys.stderr.buffer.write({error_wire!r}); sys.exit({code})']

                def rewrite_output(command, **kwargs):
                    kwargs.pop('timeout_seconds', None)
                    return real_run(child, timeout=5, **kwargs)

                try:
                    with patch.object(subprocess_policy, 'run_subprocess', side_effect=rewrite_output):
                        raw = mcp_rewrite_tools._execute_rewrite_diff_command(['controlled-producer']) if case == 'diff_content' else mcp_rewrite_tools._execute_index_search_command(['controlled-producer'], pattern='x', path=str(fixture))
                    output = json.loads(raw)
                except Exception as error:
                    output = {'exception': type(error).__name__, 'message': str(error)}
                if case == 'index_partial':
                    passed = output.get('result_incomplete') is True and output.get('incomplete_reason_class') == 'scan_limit' and output.get('matches') == partial['matches'] and output.get('total_matches') == 1 and 'error' not in output
                elif case == 'diff_content':
                    passed = output.get('diff') == '--- a\n+++ b\n-\ufffd\n'
                else:
                    passed = output.get('error', {}).get('code') == ('invalid_output' if code == 0 else 'invalid_input')
                row('decoding_mcp_' + case, {'wire_hex': wire.hex(), 'producer_exit': code, 'consumer': output}, passed)

            if os.name == 'nt':
                from tensor_grep.cli import codemap, evidence_receipt
                for consumer, wire in [('codemap', b'caf\xe9.txt\0'), ('revision', b'## main\0 M caf\xe9.txt\0')]:
                    child = [sys.executable, '-B', '-c', f'import sys; sys.stdout.buffer.write({wire!r})']

                    def git_paths(command, **kwargs):
                        kwargs.pop('timeout_seconds', None)
                        return real_run(child, timeout=5, **kwargs)

                    module = codemap if consumer == 'codemap' else evidence_receipt
                    try:
                        with patch.object(module, 'run_subprocess', side_effect=git_paths):
                            output = codemap._tracked_file_set(fixture) if consumer == 'codemap' else evidence_receipt._repo_revision_identity_excluding(fixture, commit_sha='0' * 40, timeout_seconds=5, exclude_prefixes=[])
                    except Exception as error:
                        output = {'exception': type(error).__name__, 'message': str(error)}
                    row('decoding_windows_git_' + consumer, {'wire_hex': wire.hex(), 'consumer': output}, output is None if consumer == 'codemap' else output.get('status') == 'unavailable' and 'path could not be represented' in output.get('reason', ''))

            rg = ripgrep_backend.RipgrepBackend()
            for use_nul in (False, True):
                wire = b' leading name\x002\nother\x0012' if use_nul else b' leading name:2\nother:12'
                config = SearchConfig(count=True, with_filename=True, null=use_nul)
                with patch.object(rg, '_build_cmd', return_value=['producer-control']), patch.object(ripgrep_backend, 'run_subprocess', side_effect=subprocess.TimeoutExpired(['producer-control'], 1, output=wire)):
                    output = rg._search_counts(['leading', 'other'], 'needle', config)
                raw = {'wire_hex': wire.hex(), 'total_matches': output.total_matches, 'total_files': output.total_files, 'paths': output.matched_file_paths, 'counts': output.match_counts_by_file, 'incomplete': output.result_incomplete, 'reason_class': output.incomplete_reason_class}
                row('decoding_timeout_counts_' + ('nul' if use_nul else 'lf'), raw, output.total_matches == 2 and output.match_counts_by_file == {' leading name': 2} and output.result_incomplete and output.incomplete_reason_class == 'timeout')

            explicit_path = 'src/snowman_\u2603.py'
            for record_type in ('match', 'context'):
                record = {'type': record_type, 'data': {'path': {'bytes': base64.b64encode(os.fsencode(explicit_path)).decode('ascii')}, 'lines': {'bytes': base64.b64encode(b'line\xff\n').decode('ascii')}, 'line_number': 1, 'absolute_offset': 0, 'submatches': []}}
                matches, paths, counts, total = rg._parse_ndjson_matches(json.dumps(record) + '\n', 'repository-root')
                raw = {'producer': record, 'matches': [{'file': item.file, 'line': item.line_number, 'text': item.text} for item in matches], 'paths': paths, 'counts': counts, 'total': total}
                row('decoding_ndjson_path_' + record_type, raw, len(matches) == 1 and matches[0].file == explicit_path and matches[0].text == 'line\ufffd')

        if 'ranking' in args.cases.split(','):
            from tensor_grep.cli import repo_map
            project = fixture / 'ranking'
            (project / 'src' / 'cli').mkdir(parents=True)
            target = project / 'src' / 'repair_env.py'
            target.write_text("def repair_environment():\n    return 'ready'\n", encoding='utf-8')
            (project / 'src' / 'cli' / 'main.py').write_text('\n'.join(f"def repair_env_action_{i}():\n    return 'repair env'\n" for i in range(24)), encoding='utf-8')
            inventory = repo_map.build_repo_map(project)
            for mode in ('render', 'edit'):
                if mode == 'render':
                    output = repo_map.build_context_render_from_map(inventory, 'repair env', max_files=1, max_sources=1, max_symbols_per_file=1)
                else:
                    output = repo_map.build_context_edit_plan_from_map(inventory, 'repair env', max_files=1, max_sources=1, max_symbols=1)
                primary = output.get('edit_plan_seed', {}).get('primary_symbol') or {}
                row('filename_' + mode, output, output['files'] == [str(target.resolve())] and primary.get('file') == str(target.resolve()) and primary.get('name') == 'repair_environment' and primary.get('line') == 1)

        if 'labels' in args.cases.split(','):
            project = fixture / 'labels'
            project.mkdir()
            target = project / 'sample.py'
            target.write_text('before\n', encoding='utf-8')
            other = project / 'other.py'
            other.write_text('original\n', encoding='utf-8')
            result = runner.invoke(main.app, ['checkpoint', 'create', str(project), '--paths', 'sample.py', '--label', '  Before \u518d\u78ba\u8a8d \U0001f9ed  ', '--json'])
            created = json.loads(result.stdout)
            row('label_create', {'exit': result.exit_code, 'payload': created}, result.exit_code == 0 and created.get('label') == 'Before \u518d\u78ba\u8a8d \U0001f9ed')
            listed = runner.invoke(main.app, ['checkpoint', 'list', str(project), '--json'])
            listed_payload = json.loads(listed.stdout)
            row('label_list', {'exit': listed.exit_code, 'payload': listed_payload}, listed.exit_code == 0 and checkpoint_list_matches(listed_payload, created['checkpoint_id'], created['label']))
            target.write_text('intermediate\n', encoding='utf-8')
            second_result = runner.invoke(main.app, ['checkpoint', 'create', str(project), '--paths', 'sample.py', '--label', created['label'], '--json'])
            second = json.loads(second_result.stdout)
            target.write_text('after\n', encoding='utf-8')
            other.write_text('must remain\n', encoding='utf-8')
            undone = runner.invoke(main.app, ['checkpoint', 'undo', created['checkpoint_id'], str(project), '--json'])
            after_list = runner.invoke(main.app, ['checkpoint', 'list', str(project), '--json'])
            after_payload = json.loads(after_list.stdout)
            row('label_scoped_undo_by_id', {'exit': undone.exit_code, 'payload': json.loads(undone.stdout), 'second_create': {'exit': second_result.exit_code, 'payload': second}, 'after_list': {'exit': after_list.exit_code, 'payload': after_payload}, 'restored': target.read_text(encoding='utf-8'), 'unscoped': other.read_text(encoding='utf-8')}, second_result.exit_code == 0 and second.get('label') == created['label'] and isinstance(second.get('checkpoint_id'), str) and second['checkpoint_id'] != created['checkpoint_id'] and undone.exit_code == 0 and target.read_text(encoding='utf-8') == 'before\n' and other.read_text(encoding='utf-8') == 'must remain\n' and after_list.exit_code == 0 and checkpoint_list_matches(after_payload, second['checkpoint_id'], created['label']))
            invalid = fixture / 'invalid-label'
            invalid.mkdir()
            result = runner.invoke(main.app, ['checkpoint', 'create', str(invalid), '--label', 'bad\nlabel', '--json'])
            row('label_invalid_no_write', {'exit': result.exit_code, 'output': result.output, 'entries': [p.name for p in invalid.iterdir()]}, result.exit_code == 2 and not any(invalid.iterdir()) and '1 to 120 printable characters' in result.output)
            from tensor_grep.cli import mcp_server
            previous_cwd = Path.cwd()
            try:
                os.chdir(fixture)
                schemas = {tool.name: tool.inputSchema for tool in asyncio.run(mcp_server.mcp.list_tools())}
                for name, arguments in [('tg_checkpoint_create', {'path': str(project), 'label': 'legacy MCP label'}), ('tg_checkpoint', {'action': 'create', 'path': str(project), 'label': 'meta MCP label'})]:
                    content, _metadata = asyncio.run(mcp_server.mcp.call_tool(name, arguments))
                    payload = json.loads(content[0].text)
                    row('label_' + name, {'schema': schemas[name], 'payload': payload}, payload.get('label') == arguments['label'] and payload.get('mcp_contract_version') == '1.12.0' and 'label' in schemas[name]['properties'])
                for action in ('list', 'undo'):
                    before_tree = snapshot_tree(project)
                    content, _metadata = asyncio.run(mcp_server.mcp.call_tool('tg_checkpoint', {'action': action, 'path': str(project), 'checkpoint_id': created['checkpoint_id'], 'label': 'rejected'}))
                    payload = json.loads(content[0].text)
                    after_tree = snapshot_tree(project)
                    row('label_mcp_reject_' + action, {'payload': payload, 'before_tree': before_tree, 'after_tree': after_tree}, refusal_unchanged(payload, before_tree, after_tree))
                for name in ('tg_checkpoint_create', 'tg_checkpoint'):
                    for literal in ('null', '["x"]', '{"a":1}'):
                        arguments = {'path': str(project), 'label': literal}
                        if name == 'tg_checkpoint':
                            arguments['action'] = 'create'
                        try:
                            content, _metadata = asyncio.run(mcp_server.mcp.call_tool(name, arguments))
                            payload = json.loads(content[0].text)
                        except Exception as error:
                            payload = {'exception': type(error).__name__, 'message': str(error)}
                        row('label_literal_' + name + '_' + literal, payload, payload.get('label') == literal)
                private_path = fixture / 'private-label-path'
                before_fixture = snapshot_tree(fixture)
                content, _metadata = asyncio.run(mcp_server.mcp.call_tool('tg_checkpoint_create', {'path': str(private_path), 'label': ''}))
                payload = json.loads(content[0].text)
                after_fixture = snapshot_tree(fixture)
                row('label_invalid_path_redacted', {'payload': payload, 'before_tree': before_fixture, 'after_tree': after_fixture}, payload.get('path') == '[refused]' and refusal_unchanged(payload, before_fixture, after_fixture))
            finally:
                os.chdir(previous_cwd)

        if args.native:
            native = Path(args.native).resolve()
            raw_version = real_run([str(native), '--version'], capture_output=True, encoding='utf-8', errors='replace', timeout=10)
            output = main._doctor_gpu_search_runtime_probe(native)
            row('real_native_gpu_observation', {'binary': str(native), 'sha256': hashlib.sha256(native.read_bytes()).hexdigest(), 'version_exit': raw_version.returncode, 'version': raw_version.stdout, 'probe': output}, raw_version.returncode == 0 and (args.version is None or raw_version.stdout.strip() == 'tg ' + args.version) and output.get('status') in {'supported', 'unsupported', 'failed_gpu_unavailable'} and (output.get('status') != 'supported' or (output.get('routing_backend') == 'NativeGpuBackend' and output.get('sidecar_used') is False)))

    print(json.dumps(report, indent=2, ensure_ascii=True))
    return 0 if report['rows'] and all(item['verdict'] == 'PASS' for item in report['rows']) else 1


if __name__ == '__main__':
    raise SystemExit(main_replay())

