"""Closed expected populations for external published-artifact replay receipts."""
import json

GROUPS = {
    'diagnostics': {
        'repair_env_utf8_malformed', 'repair_env_absent_output', 'repair_env_timeout',
        'gpu_proof_NativeGpuBackend_False', 'gpu_proof_GpuSidecar_True',
        'gpu_proof_NativeGpuBackend_None', 'gpu_non_object_json',
    },
    'decoding': {
        'decoding_ast_positive', 'decoding_ast_malformed_stderr',
        'decoding_ast_malformed_stdout', 'decoding_ast_utf8_input', 'decoding_git_error',
        'decoding_agent_exit_0', 'decoding_doctor_exit_0', 'decoding_agent_exit_17',
        'decoding_doctor_exit_17', 'decoding_pip_stdout_valid',
        'decoding_pip_stdout_malformed', 'decoding_pip_stderr_valid',
        'decoding_pip_stderr_malformed', 'decoding_mcp_index_partial',
        'decoding_mcp_diff_content', 'decoding_mcp_index_invalid_protocol',
        'decoding_mcp_index_failed_protocol', 'decoding_timeout_counts_lf',
        'decoding_timeout_counts_nul', 'decoding_ndjson_path_match',
        'decoding_ndjson_path_context',
    },
    'ranking': {'filename_render', 'filename_edit'},
    'labels': {
        'label_create', 'label_list', 'label_scoped_undo_by_id', 'label_invalid_no_write',
        'label_tg_checkpoint_create', 'label_tg_checkpoint', 'label_mcp_reject_list',
        'label_mcp_reject_undo', 'label_literal_tg_checkpoint_create_null',
        'label_literal_tg_checkpoint_create_["x"]',
        'label_literal_tg_checkpoint_create_{"a":1}', 'label_literal_tg_checkpoint_null',
        'label_literal_tg_checkpoint_["x"]', 'label_literal_tg_checkpoint_{"a":1}',
        'label_invalid_path_redacted',
    },
    'native': set(),
}
NATIVE = 'real_native_gpu_observation'
FRONTDOOR = {
    'native_cli_label_create', 'native_cli_label_list', 'native_cli_scoped_undo_by_id',
    'native_cli_invalid_label_no_write',
}


def expected_issues(cases, *, windows, native):
    selected = set(cases.split(','))
    if not selected or selected - GROUPS.keys() or ('native' in selected and not native):
        raise ValueError('invalid selected replay cases')
    expected = set().union(*(GROUPS[name] for name in selected))
    if windows and 'decoding' in selected:
        expected.update({'decoding_windows_git_codemap', 'decoding_windows_git_revision'})
    if native:
        expected.add(NATIVE)
    return expected


def validate_report(raw, *, version, expected, compiled_extension=False):
    payload = json.loads(raw)
    if not isinstance(payload, dict) or payload.get('version') != version:
        raise ValueError('report object/version mismatch')
    if not isinstance(payload.get('package'), str) or not payload['package']:
        raise ValueError('missing package provenance')
    if compiled_extension:
        extension = payload.get('compiled_extension')
        if not isinstance(extension, dict) or not isinstance(extension.get('path'), str):
            raise ValueError('missing compiled-extension provenance')
        digest = extension.get('sha256')
        if not isinstance(digest, str) or len(digest) != 64 or set(digest) - set('0123456789abcdef'):
            raise ValueError('invalid compiled-extension digest')
    rows = payload.get('rows')
    if not isinstance(rows, list) or not rows:
        raise ValueError('missing replay row population')
    issues = []
    for row in rows:
        if not isinstance(row, dict) or not isinstance(row.get('issue'), str):
            raise ValueError('invalid replay row shape')
        if row.get('verdict') != 'PASS' or not isinstance(row.get('raw'), dict):
            raise ValueError('failing row or missing raw evidence: ' + row['issue'])
        issues.append(row['issue'])
    if len(issues) != len(set(issues)) or set(issues) != expected:
        raise ValueError('replay population mismatch or duplicate issues')
    return payload

