"""Synthetic false-clearance controls; not actual review or merged-source proof."""
from copy import deepcopy
import json
from pathlib import Path

from closure_validation import HEAD, MARKER, STAMP_COUNTS, validate_merged_source, validate_reviews
from published_checkpoint_discovery import EXPECTED, TAIL
from replay_validation import expected_issues

e = Path(__file__).parent
checks = []
line = MARKER + json.dumps({'head': HEAD, 'verdict': 'SHIP', 'verified': True, 'action': 'GO'})
opus = {'is_error': False, 'terminal_reason': 'completed', 'api_error_status': None, 'result': line}
quota = {'is_error': True, 'api_error_status': 429}


def accepts(name, operation):
    operation()
    checks.append({'case': name, 'outcome': 'PASS'})


def rejects(name, operation, reason):
    try:
        operation()
    except ValueError as error:
        assert str(error) == reason, (name, str(error))
        checks.append({'case': name, 'outcome': 'PASS', 'expected_refusal': reason})
    else:
        raise AssertionError('False clearance: ' + name)


accepts('exact synthetic review pair accepted', lambda: validate_reviews(line, line, opus, quota))
for name, report, reason in [
    ('missing verdict', 'Prose only', 'missing or duplicate structured review verdict'),
    ('duplicate verdict', line + '\n' + line, 'missing or duplicate structured review verdict'),
    ('wrong review head', line.replace(HEAD, '0' * 40), 'final review does not clear exact labels head'),
    ('FIX-FIRST', line.replace('SHIP', 'FIX-FIRST'), 'final review does not clear exact labels head'),
    ('not verified', line.replace('true', 'false'), 'final review does not clear exact labels head'),
    ('numeric verified', line.replace('true', '1'), 'final review does not clear exact labels head'),
    ('NO-GO', line.replace('"GO"', '"NO-GO"'), 'final review does not clear exact labels head'),
]:
    rejects('Sol ' + name, lambda report=report: validate_reviews(report, line, opus, quota), reason)
    rejects('Opus ' + name, lambda report=report: validate_reviews(line, report, opus, quota), reason)
for key, value in [('is_error', True), ('terminal_reason', 'api_error'), ('api_error_status', 429)]:
    altered = {**opus, key: value}
    rejects('failed Opus ' + key, lambda altered=altered: validate_reviews(line, line, altered, quota), 'Opus invocation did not complete successfully')
rejects('raw result lacks verdict', lambda: validate_reviews(line, line, {**opus, 'result': 'No verdict'}, quota), 'missing or duplicate structured review verdict')
rejects('historical failure laundered', lambda: validate_reviews(line, line, opus, {'is_error': False, 'api_error_status': None}), 'historical quota failure evidence mismatch')

root = 'C:/dev/projects/tg-dogfood-main-verify'
merge = 'a' * 40
pr = {'merged': True, 'head': {'sha': HEAD}, 'merge_commit_sha': merge}
tools = [{'name': name, 'description': f'Legacy per-function tool; meta-tool `tg_checkpoint` (action={action}) covers this operation. {TAIL}'} for name, action in EXPECTED.items()]
stamps = {path: {'old_version': '1.123.22', 'new_version': '1.123.23', 'replacement_count': count, 'reviewed_mode': '100644', 'parent_mode': '100644', 'merged_mode': '100644', 'reviewed_blob': 'd' * 40, 'parent_blob': 'e' * 40, 'merged_blob': 'e' * 40, 'exact_raw_version_substitution': True} for path, count in STAMP_COUNTS.items()}
proof = {'reviewed_head': HEAD, 'actual_head': merge, 'actual_tree': 'b' * 40, 'expected_three_way_tree': 'b' * 40, 'source_test_trees_match': True, 'script_release_stamp_changes': stamps, 'advertised_checkpoint_tools': tools, 'worktree': root}
gate = {'head_sha_at_start': merge, 'status_at_start': '', 'exit_code': 0, 'root': root}
report = {'version': '1.123.19', 'package': root + '/src/tensor_grep/__init__.py', 'compiled_extension': {'path': root + '/src/tensor_grep/rust_core.pyd', 'sha256': 'c' * 64}, 'rows': [{'issue': name, 'verdict': 'PASS', 'raw': {}} for name in sorted(expected_issues('diagnostics,decoding,ranking,labels', windows=True, native=False))]}
accepts('bound synthetic merge proof accepted', lambda: validate_merged_source(proof, gate, json.dumps(report), pr))
for key, value, reason in [
    ('actual_head', 'd' * 40, 'merged proof head mismatch'),
    ('reviewed_head', 'd' * 40, 'merged proof head mismatch'),
    ('actual_tree', 'd' * 40, 'merged tree proof mismatch'),
    ('source_test_trees_match', False, 'merged source trees differ from review'),
    ('advertised_checkpoint_tools', [], 'merged discovery descriptions fail contract'),
    ('worktree', root + '-stale', 'merged source worktree mismatch'),
]:
    altered = {**proof, key: value}
    rejects('merge ' + key, lambda altered=altered: validate_merged_source(altered, gate, json.dumps(report), pr), reason)
for key, value in [('head_sha_at_start', 'd' * 40), ('status_at_start', 'M src/file.py'), ('exit_code', 1)]:
    altered = {**gate, key: value}
    rejects('source replay ' + key, lambda altered=altered: validate_merged_source(proof, altered, json.dumps(report), pr), 'merged source replay did not pass clean exact head')
rejects('unmerged PR', lambda: validate_merged_source(proof, gate, json.dumps(report), {**pr, 'merged': False}), 'merged labels PR identity mismatch')
altered = {**report, 'package': root + '-stale/src/tensor_grep/__init__.py'}
rejects('stale replay source', lambda: validate_merged_source(proof, gate, json.dumps(altered), pr), 'merged replay source mismatch')
altered = {**report, 'rows': report['rows'][:-1]}
rejects('missing source case', lambda: validate_merged_source(proof, gate, json.dumps(altered), pr), 'replay population mismatch or duplicate issues')
altered = deepcopy(report)
altered['rows'][0]['verdict'] = 'FAIL'
rejects('failing source case', lambda: validate_merged_source(proof, gate, json.dumps(altered), pr), 'failing row or missing raw evidence: ' + altered['rows'][0]['issue'])

output = {'kind': 'Synthetic closure validation controls; not actual review, merge, CI or publication evidence', 'checks': checks}
(e / 'closure-validation-controls.json').write_text(json.dumps(output, indent=2), encoding='utf-8')
print(json.dumps({'count': len(checks), **output}))
